"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["57086"],{73082(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.escala_na_forma_objetiva","status":422,"titulo":"A escala de atendimento s\xf3 se aplica \xe0 etapa de avalia\xe7\xe3o humana"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.escala_na_forma_objetiva","requisitos":["UNI-REQ-0175"],"oQueAconteceu":["A etapa declarou a forma `OBJETIVA` e tamb\xe9m uma `escalaDeAtendimento`. A escala existe\\npara a banca escolher, em cada item, o n\xedvel que o candidato atendeu; na avalia\xe7\xe3o\\nobjetiva a nota sai do gabarito ou da leitora \xf3ptica e n\xe3o h\xe1 quem escolha.","A recusa vale j\xe1 na grava\xe7\xe3o, tamb\xe9m em rascunho, e chega no array `errors[]`, no campo\\n`escalaDeAtendimento` da etapa. Enquanto a forma n\xe3o estiver declarada, a escala \xe9\\naceita em rascunho; a falta da forma \xe9 cobrada na publica\xe7\xe3o."],"comoResolver":["Escolha um dos dois caminhos:","- se a nota \xe9 obtida por gabarito ou leitora, remova a escala de atendimento (os itens\\n  de avalia\xe7\xe3o continuam permitidos: s\xe3o os blocos da prova);\\n- se a nota \xe9 dada pela banca, declare a forma como `HUMANA` e mantenha a escala.","Se a resposta trouxer mais de uma viola\xe7\xe3o em `errors[]`, corrija todas antes de\\nreenviar."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);